function setup(){
  createCanvas(640, 480);
  rectMode(CENTER);
  fill(20);
  stroke(255, 251, 249);
  strokeWeight(4);
}

function draw(){
  background(255, 251, 249);
  translate(width / 2, height / 2);
  let num = 10;
  let intervalX = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 40, -40);
  let intervalY = map(abs((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2), 0, width / 2, 0, -20);
  let rectX = 100;
  let rectY = 200;
  let tilt = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -20, 20);
  for(let i = num - 1; i > 0; i--){
    push();
    let rhytm = map(pow(abs(sin(frameCount * 0.03 - i * 0.3)), 50), 0, 1, 0, -50)
                * map(abs((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2), 0, width / 2, 0, 1);
    translate(intervalX * (i - num / 2.0), intervalY * (i - num / 2.0) + rhytm);
    beginShape();
    vertex(-rectX / 2.0, -rectY / 2.0 + tilt);
    vertex(rectX / 2.0, -rectY / 2.0 - tilt);
    vertex(rectX / 2.0, rectY / 2.0 - tilt);
    vertex(-rectX / 2.0, rectY / 2.0 + tilt);
    endShape(CLOSE);
    pop();
  }
}
